import{_ as t,o as a,c as n,a2 as o}from"./chunks/framework.CPHNBVkq.js";const s="/corbi/screenshots/channel-create.png",u=JSON.parse('{"title":"Creating a Channel","description":"","frontmatter":{},"headers":[],"relativePath":"guide/channels-create.md","filePath":"guide/channels-create.md"}'),r={name:"guide/channels-create.md"};function l(h,e,i,c,g,d){return a(),n("div",null,[...e[0]||(e[0]=[o('<h1 id="creating-a-channel" tabindex="-1">Creating a Channel <a class="header-anchor" href="#creating-a-channel" aria-label="Permalink to &quot;Creating a Channel&quot;">​</a></h1><p>A channel decides what shows up in your <a href="./pulse-feed.html">Pulse feed</a>. This page walks through creating one. If you&#39;d like background on what each setting means first, see <a href="./channels.html">About Channels</a>.</p><h2 id="open-the-create-form" tabindex="-1">Open the create form <a class="header-anchor" href="#open-the-create-form" aria-label="Permalink to &quot;Open the create form&quot;">​</a></h2><p>There are a few ways to get to the create screen:</p><ul><li><strong>Settings → Manage Channels → Create Channel</strong>, or</li><li>From an empty Pulse feed, select <strong>Create Channel</strong>.</li></ul><p><img src="'+s+'" alt="The Create Channel form"></p><h2 id="fill-in-the-channel" tabindex="-1">Fill in the channel <a class="header-anchor" href="#fill-in-the-channel" aria-label="Permalink to &quot;Fill in the channel&quot;">​</a></h2><p>The form has four fields:</p><ol><li><strong>Channel Name</strong> — give it a name you&#39;ll recognize. It must be between 3 and 50 characters.</li><li><strong>Channel Scope</strong> — choose how your tags combine: <strong>Broad</strong> (match <em>any</em> tag) or <strong>Narrow</strong> (match <em>all</em> tags). This only changes anything once you add two or more tags. See <a href="./channels.html#channel-scope">Channel Scope</a> if you&#39;re unsure.</li><li><strong>Category</strong> — select the kind of business event this channel follows. This is required, and it determines which tags are available next.</li><li><strong>Channel Tags</strong> — optionally narrow the channel to specific items within the category. Open the tag picker, choose the tags you want, and they&#39;ll appear in a list below. Remove a tag by selecting it in that list.</li></ol><div class="tip custom-block"><p class="custom-block-title">Choose the category before tags</p><p>The available tags come from the category you pick, so set the <strong>Category</strong> first. If you change the category later, double-check your tags still make sense.</p></div><h2 id="save" tabindex="-1">Save <a class="header-anchor" href="#save" aria-label="Permalink to &quot;Save&quot;">​</a></h2><p>Select <strong>Save</strong> to create the channel. The <strong>Save</strong> button stays disabled until the form is valid — you&#39;ll need at least a name (3+ characters) and a category.</p><p>To back out without creating anything, select <strong>Cancel</strong>.</p><p>Once saved, your new channel starts feeding updates into your Pulse feed. Open <strong>Pulse</strong> to see them, and use the channel selector at the top to view this channel on its own. See <a href="./pulse-feed.html#filtering-by-channel">Pulse Feed</a>.</p><div class="info custom-block"><p class="custom-block-title">Nothing in the feed yet?</p><p>A brand-new channel may take a little time to fill up, and some categories are quieter than others. If it stays empty, try a <strong>Broad</strong> scope or fewer tags. See <a href="./pulse-feed.html#when-the-feed-is-empty">When the feed is empty</a>.</p></div>',15)])])}const m=t(r,[["render",l]]);export{u as __pageData,m as default};
